    state: 'AZ',
    alertLevel: 'high',
    sources: ["Arizona Attorney General's Office", '12News', 'AZFamily'],
    sourceUrl: 'https://www.azag.gov/press-release/attorney-general-mayes-announces-prison-sentences-fraudulent-life-insurance-scheme',
